export class Controls{constructor(canvas){this.keys={};this.touch={x:0,z:0};this.jump=false;addEventListener('keydown',e=>this.keys[e.code]=true);addEventListener('keyup',e=>this.keys[e.code]=false);const pad=document.querySelector('#pad'),stick=document.querySelector('#stick');let active=false;const move=e=>{if(!active)return;const r=pad.getBoundingClientRect(),dx=e.clientX-(r.left+r.width/2),dy=e.clientY-(r.top+r.height/2),m=Math.min(42,Math.hypot(dx,dy)),a=Math.atan2(dy,dx);this.touch.x=Math.cos(a)*m/42;this.touch.z=Math.sin(a)*m/42;stick.style.transform=`translate(${this.touch.x*38}px,${this.touch.z*38}px)`;};pad.addEventListener('pointerdown',e=>{active=true;pad.setPointerCapture(e.pointerId);move(e);});pad.addEventListener('pointermove',move);const end=()=>{active=false;this.touch={x:0,z:0};stick.style.transform='';};pad.addEventListener('pointerup',end);pad.addEventListener('pointercancel',end);}
read(){const x=(this.keys.ArrowRight||this.keys.KeyD?1:0)-(this.keys.ArrowLeft||this.keys.KeyA?1:0)+this.touch.x;const z=(this.keys.ArrowDown||this.keys.KeyS?1:0)-(this.keys.ArrowUp||this.keys.KeyW?1:0)+this.touch.z;const jump=this.jump||this.keys.Space;this.jump=false;return {x:Math.max(-1,Math.min(1,x)),z:Math.max(-1,Math.min(1,z)),jump};}}
